// Save a crafted tool named cache_echo that returns the text it is given
const result = await workspace.createTool(
  'cache_echo',
  'Echo tool: takes a text argument and returns that same text.',
  `async (input) => {
  if (typeof input === 'string') return input;
  if (input && typeof input === 'object') {
    if (typeof input.text === 'string') return input.text;
    if (Object.keys(input).length === 1) return Object.values(input)[0];
  }
  return String(input == null ? '' : input);
}`
);
